                    group += char

        return groups

    def remove_spaces(groups):
        return [group.replace(' ', '') for group in groups]

    def separate_groups(groups):
        return groups

    def is_balanced(group):
        stack = []
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack or stack.pop() != '(':
                    return False
        return not stack

    extracted_groups = extract_groups(paren_string)
    cleaned_groups = remove_spaces(extracted_groups)
    separated_groups = separate_groups(cleaned_groups)
    balanced_groups = [group for group in separated_groups if is_balanced(group)]

    return balanced_groups

